const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 1880 }, deviceScaleFactor: 2 });
  const htmlPath = 'file://' + path.resolve('/app/output/hunger_crisis_poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle' });
  await page.evaluate(async () => {
    if (document.fonts && document.fonts.ready) await document.fonts.ready;
    document.documentElement.className = 'theme-dark';
    document.querySelectorAll('.viz-menu').forEach((el) => { el.style.display = 'none'; });
  });
  const poster = await page.locator('#poster');
  await poster.screenshot({ path: '/app/output/final_poster.png', omitBackground: false });
  await browser.close();
})();
